#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-only
"""The off-screen strip is one picture high, and that picture still fits.

The panel is three strips that never share the buffer: header, main area,
knob row. The strip must be exactly the taller of those, and drawing each
one must not be clamped.
"""
import re
import subprocess
import sys
import tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
GFX = (ROOT / "firmware/src/gfx.c").read_text()
UI = (ROOT / "firmware/src/app/ui.c").read_text()
MAIN = (ROOT / "firmware/src/app/main_fm1.c").read_text()
SMC = (ROOT / "firmware/src/app/smc_mixer.c").read_text()


def define(text, name):
    m = re.search(rf"#define {name} (\d+)u?", text)
    if not m:
        raise SystemExit(f"missing {name}")
    return int(m.group(1))


def main():
    rows = define(GFX, "CV_ROWS")
    band = define(UI, "BAND_H")
    hdr = define(UI, "HDR_H")
    knob = define(UI, "KNOB_H")
    if rows != 2 * band:
        raise SystemExit(f"strip is {rows} rows, main area is {2 * band}")
    if hdr + rows + knob != 240:
        raise SystemExit(f"strips {hdr}+{rows}+{knob} do not tile 240")
    if knob > rows or hdr > rows:
        raise SystemExit("a strip is taller than the buffer")
    for label, text in ("ui", UI), ("main", MAIN), ("smc", SMC):
        for n in (int(x) for x in re.findall(r"cv_begin\(\s*240\s*,\s*(\d+)", text)):
            if n > rows:
                raise SystemExit(f"{label} draws {n} rows into a {rows}-row strip")
    block = re.search(r"#ifdef CV_ROWS\n(.*?)#endif", UI, re.S)
    if not block:
        raise SystemExit("ui.c is missing the screen-strip asserts")
    src = """
#include <stdint.h>
#include <stdio.h>
static void lcd_sync(void) {}
static void lcd_blit(uint32_t x, uint32_t y, uint32_t w, uint32_t h, const uint16_t *p)
{ (void)x; (void)y; (void)w; (void)h; (void)p; }
#include "gfx.c"
#define HDR_H %d
#define BAND_H %d
#define KNOB_H %d
%s
int main(void) {
    if (CV_ROWS != %d || CV_MAX != 240u * CV_ROWS) return 1;
    if (sizeof(cv_px) != (size_t)CV_MAX * sizeof(uint16_t)) return 2;
    cv_begin(240, %d, 0);
    if (cv_h != %du) return 3;
    cv_begin(240, %d, 0);
    if (cv_h != %du) return 4;
    cv_begin(240, %d, 0);
    if (cv_h != %du) return 5;
    printf("canvas strip %%u bytes (was %%u)\\n", (unsigned)sizeof(cv_px), 240u * 144u * 2u);
    return 0;
}
""" % (hdr, band, knob, block.group(1), rows, 2 * band, 2 * band, knob, knob, hdr, hdr)
    with tempfile.TemporaryDirectory() as tmp:
        tmp_path = Path(tmp)
        (tmp_path / "felucca_font.h").write_text("/* host stub: this check draws no glyphs */\n")
        path = tmp_path / "canvas_strip_test.c"
        path.write_text(src)
        bin_path = tmp_path / "canvas_strip_test"
        subprocess.check_call(
            ["cc", "-std=gnu99", "-Wall", "-Wextra", "-Werror", "-Wno-unused-function",
             "-I", tmp, "-I", "firmware/src",
             "-o", str(bin_path), str(path)],
            cwd=ROOT,
        )
        subprocess.check_call([str(bin_path)])
    print(f"canvas strip: {rows} rows, main {2 * band}, knob {knob}, header {hdr}")
    return 0


if __name__ == "__main__":
    sys.exit(main())

/* SPDX-License-Identifier: GPL-3.0-only */
/* BF-023: a gesture queued for a lane must not replay after another pattern ran.
 * Real motion.c host test; no mocking of motion_step, request, or release code. */
#include <stdio.h>
#include <string.h>
#include "../../firmware/src/seq/motion.h"

static lane_t lanes[NLANE];
static motion_t motion;
static int knob, emitted, errors;
static int base(void *ctx, int t, int v, int i)
{
    (void)ctx; (void)t; (void)v; (void)i;
    return knob;
}
static void apply(void *ctx, int t, int v, int i, int value)
{
    (void)ctx; (void)t; (void)v; (void)i;
    emitted = value;
}
#define CHECK(cond, label) do { \
    if (!(cond)) { fprintf(stderr, "FAIL: %s\n", label); errors++; } \
} while (0)

static void reset(void)
{
    memset(lanes, 0, sizeof lanes);
    knob = emitted = 64;
    motion_init(&motion, lanes);
    motion.base = base;
    motion.apply = apply;
}

int main(void)
{
    int k;
    /* A REC request arrives just before the part advances to a different pattern.
     * Its target lane is inactive there, so it must NOT write on re-entry. */
    reset();
    k = motion_alloc(lanes, 2, 0, 2, 0, 0);
    CHECK(k == 0, "REC fixture allocated first lane");
    lanes[k].val[5] = 41;
    motion_step(&motion, 0, 2, 4, 5, 16);
    motion_req_rec(&motion, k);
    knob = emitted = 79;
    motion_step(&motion, 1, 7, 1, 2, 16); /* other part must not consume it */
    CHECK(motion.rt[k].rec_req == 1, "unrelated part preserves queue");
    motion_step(&motion, 0, 3, 0, 1, 16); /* different pattern consumes it */
    CHECK(motion.rt[k].rec_req == 0, "pattern switch discards obsolete REC intent");
    CHECK(lanes[k].val[5] == 41, "unrelated pattern leaves prior p-lock intact");
    motion_step(&motion, 0, 2, 5, 6, 16);
    CHECK(lanes[k].val[5] == 41, "re-entered pattern does not record stale REC");
    CHECK(emitted == 41, "re-entered pattern plays its existing p-lock");
    knob = emitted = 97;
    motion_req_rec(&motion, k);
    motion_step(&motion, 0, 2, 6, 7, 16);
    CHECK(lanes[k].val[6] == 97, "fresh post-reentry REC request still records");

    /* A queued nonrecording HOLD must likewise not suppress playback after
     * returning from a different pattern several steps later. */
    reset();
    k = motion_alloc(lanes, 2, 0, 2, 0, 0);
    CHECK(k == 0, "HOLD fixture allocated first lane");
    lanes[k].val[5] = 36;
    motion_step(&motion, 0, 2, 4, 5, 16);
    motion_req_hold(&motion, k);
    knob = emitted = 88;
    motion_step(&motion, 0, 3, 0, 1, 16);
    CHECK(motion.rt[k].hold_req == 0, "pattern switch discards obsolete HOLD intent");
    motion_step(&motion, 0, 3, 1, 2, 16);
    motion_step(&motion, 0, 2, 5, 6, 16);
    CHECK(emitted == 36, "re-entered pattern applies p-lock, not stale HOLD");
    CHECK(motion.rt[k].hold_left == 0, "stale HOLD does not inhibit next pass");
    knob = emitted = 90;
    motion_req_hold(&motion, k);
    motion_step(&motion, 0, 2, 6, 7, 16);
    CHECK(emitted == 90 && motion.rt[k].hold_left == 15,
          "fresh post-reentry HOLD request still wins one pass");
    printf("motion-pattern-pending: %s (%d failures)\n", errors ? "FAIL" : "PASS", errors);
    return errors != 0;
}

